:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --accent: #f9c74f;
  --text: #f0f0f5;
  --muted: #9a9ab0;
  --danger: #e76f51;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  padding: 28px 24px;
  border-radius: 12px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  border: 2px solid var(--accent);
}
h1 { margin: 0 0 8px; font-size: 1.6rem; letter-spacing: 1px; }
.counts { margin: 0 0 20px; color: var(--muted); font-size: 0.95rem; }
.counts span { color: var(--accent); font-weight: 700; }
.add-row { display: flex; gap: 8px; margin-bottom: 20px; }
#todo-input {
  flex: 1;
  padding: 10px 12px;
  border-radius: 8px;
  border: 2px solid var(--muted);
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
}
#todo-input:focus { outline: none; border-color: var(--accent); }
button {
  padding: 10px 16px;
  border-radius: 8px;
  border: 2px solid var(--accent);
  background: var(--accent);
  color: var(--bg);
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
}
button:hover { background: #ffd966; }
button:active { transform: scale(0.96); }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.todo-list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg);
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--muted);
}
.todo-item input[type="checkbox"] {
  width: 20px; height: 20px; accent-color: var(--accent); cursor: pointer;
}
.todo-item .todo-text { flex: 1; word-break: break-word; }
.todo-item.done .todo-text { text-decoration: line-through; color: var(--muted); }
.todo-item .delete {
  background: transparent;
  border: 2px solid var(--danger);
  color: var(--danger);
  padding: 4px 10px;
  font-size: 0.9rem;
}
.todo-item .delete:hover { background: var(--danger); color: var(--text); }
.visually-hidden {
  position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 20px 16px; }
  h1 { font-size: 1.4rem; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const form = document.getElementById('todo-form');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');
let nextId = 1;
const tasks = [];

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function renderTask(task) {
  const li = document.createElement('li');
  li.className = 'todo-item' + (task.done ? ' done' : '');
  li.dataset.id = task.id;

  const check = document.createElement('input');
  check.type = 'checkbox';
  check.id = 'todo-check-' + task.id;
  check.checked = task.done;
  check.setAttribute('aria-label', 'Mark task ' + task.id + ' complete');
  check.addEventListener('change', () => {
    task.done = check.checked;
    li.classList.toggle('done', task.done);
    updateCounts();
  });

  const span = document.createElement('span');
  span.className = 'todo-text';
  span.id = 'todo-text-' + task.id;
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'delete';
  del.id = 'todo-delete-' + task.id;
  del.textContent = 'Delete';
  del.setAttribute('aria-label', 'Delete task ' + task.id);
  del.addEventListener('click', () => {
    const idx = tasks.findIndex(t => t.id === task.id);
    if (idx !== -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  li.append(check, span, del);
  list.appendChild(li);
}

function addTask(text) {
  const trimmed = text.trim();
  if (!trimmed) return;
  const task = { id: nextId++, text: trimmed, done: false };
  tasks.push(task);
  renderTask(task);
  updateCounts();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  addTask(input.value);
  input.value = '';
  input.focus();
});

updateCounts();
